import { resolve } from 'node:path'
import { chmod } from 'node:fs/promises'
import { createHash, randomBytes } from 'node:crypto'

import { atomicWrite } from '../storage/index.js'

const path = resolve(
  process.argv[2] ??
    process.env.OWNER_KEY_HASH_FILE ??
    'secrets/owner-key.sha256',
)
const key = randomBytes(32).toString('base64url')
await atomicWrite(path, `${createHash('sha256').update(key).digest('hex')}\n`)
// Only the digest is stored. Docker's unprivileged server must also be able
// to read a hash generated by root on the host or in the setup container.
await chmod(path, 0o644)
process.stderr.write(
  `SHA-256 hash saved to ${path}. Store the following key on the owner server.\n`,
)
process.stdout.write(`${key}\n`)
